attributes.visState:
{"title": "Network geo", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "title": {
  "text": "Firewall hucum menbeleri"
 },
 "config": {
  "kibana": {
   "type": "map",
   "mapStyle": "default",
   "latitude": 30,
   "longitude": 15,
   "zoom": 1.5,
   "controlsDirection": "vertical"
  }
 },
 "data": [
  {
   "name": "table",
   "url": {
    "%context%": true,
    "%timefield%": "@timestamp",
    "index": "soc-network-*",
    "body": {
     "size": 0,
     "aggs": {
      "f": {
       "filter": {
        "exists": {
         "field": "source.geo.location"
        }
       },
       "aggs": {
        "c": {
         "terms": {
          "field": "source.geo.country_name",
          "size": 100
         },
         "aggs": {
          "loc": {
           "geo_centroid": {
            "field": "source.geo.location"
           }
          }
         }
        }
       }
      }
     }
    }
   },
   "format": {
    "property": "aggregations.f.c.buckets"
   },
   "transform": [
    {
     "type": "geopoint",
     "projection": "projection",
     "fields": [
      "loc.location.lon",
      "loc.location.lat"
     ],
     "as": [
      "x",
      "y"
     ]
    }
   ]
  }
 ],
 "scales": [
  {
   "name": "r",
   "type": "sqrt",
   "domain": {
    "data": "table",
    "field": "doc_count"
   },
   "range": [
    150,
    4000
   ]
  }
 ],
 "marks": [
  {
   "type": "symbol",
   "from": {
    "data": "table"
   },
   "encode": {
    "update": {
     "x": {
      "field": "x"
     },
     "y": {
      "field": "y"
     },
     "size": {
      "scale": "r",
      "field": "doc_count"
     },
     "shape": {
      "value": "circle"
     },
     "fill": {
      "value": "#e45756"
     },
     "fillOpacity": {
      "value": 0.55
     },
     "stroke": {
      "value": "#b22222"
     },
     "strokeWidth": {
      "value": 1.5
     },
     "tooltip": {
      "signal": "{'olke': datum.key, 'hadise': datum.doc_count}"
     }
    }
   }
  }
 ]
}"}}
